class Solution:
    def minEdgeReversals(self, n: int, edges: List[List[int]]) -> List[int]:
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append((v, 0))
            g[v].append((u, 1))
        parent = [-1] * n
        dirp = [0] * n
        cost = [0] * n
        order = []
        st = [0]
        while st:
            u = st.pop(); order.append(u)
            for v, w in g[u]:
                if v != parent[u]:
                    parent[v] = u; dirp[v] = w
                    cost[v] = cost[u] + w
                    st.append(v)
        ans = [0] * n
        for v in order:
            if v != 0:
                ans[v] = ans[parent[v]] + (1 if dirp[v] == 0 else -1)
        return ans

