class Solution {
    public int[] minEdgeReversals(int n, int[][] edges) {
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(new int[]{e[1], 0}); g.get(e[1]).add(new int[]{e[0], 1}); }
        int[] parent = new int[n], dirp = new int[n], ans = new int[n];
        java.util.Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        Deque<Integer> st = new ArrayDeque<>(); st.push(0);
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (int[] nb : g.get(u)) {
                int v = nb[0], w = nb[1];
                if (v != parent[u]) { parent[v] = u; dirp[v] = w; ans[v] = 0; st.push(v); }
            }
        }
        // recompute root cost via parents
        int[] cost = new int[n];
        for (int v : order) if (v != 0) cost[v] = cost[parent[v]] + dirp[v];
        ans[0] = cost[0];
        for (int v : order) if (v != 0) ans[v] = ans[parent[v]] + (dirp[v] == 0 ? 1 : -1);
        return ans;
    }
}

